package polymorphism.assigment_problems;

import java.util.*;public class HostelElectricityBill {interface Room{double bill();}static class Single implements Room{int u;Single(int u){this.u=u;}public double bill(){return u*8.0;}}static class Shared implements Room{int u,o;Shared(int u,int o){this.u=u;this.o=o;}public double bill(){return u*6.0/o;}}static class AC implements Room{int u;AC(int u){this.u=u;}public double bill(){return u*10.0+200;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next();int u=s.nextInt();Room r=t.equals("SINGLE")?new Single(u):t.equals("SHARED")?new Shared(u,s.nextInt()):new AC(u);double b=r.bill();System.out.printf(Locale.US,"%s: %.2f%n",t,b);total+=b;}System.out.printf(Locale.US,"Total: %.2f%n",total);}}
